# Now let me verify the rule more thoroughly on both demos
# Test if the pattern holds: output[i] = color_swap(input[i] where diff(input[i-1], input[i]))

from collections import Counter

def get_colors(grid):
    c = Counter()
    for row in grid:
        for cell in row:
            c[cell] += 1
    bg = max(c, key=c.get)
    others = sorted(set(c.keys()) - {bg})
    if len(others) == 0:
        return bg, None
    return bg, others[0]

def transform_demo1(grid):
    output = []
    for row in grid:
        output.append(list(row))

    colors = get_colors(input1)
    bg, other = colors[0], colors[1]

    for i in range(1, len(output)):
        prev_row = input1[i-1]
        curr_row = output[i]

        for j in range(len(curr_row)):
            if prev_row[j] != curr_row[j]:
                # Swap colors
                if curr_row[j] == bg:
                    curr_row[j] = other
                else:
                    curr_row[j] = bg

    return output

